js:
var root_ = root;
var art = root.querySelector('.mde-inbox-zero-art');
var compose = root.querySelector('.mde-inbox-zero-primary');
var t = 0;
if (compose && art) {
  compose.addEventListener('click', function () {
    root_.classList.remove('is-launch');
    void art.offsetWidth;
    root_.classList.add('is-launch');
    clearTimeout(t);
    t = setTimeout(function () {
      if (!root_.isConnected) return;
      root_.classList.remove('is-launch');
    }, 1500);
  });
}

