var input = root.querySelector('.mde-search-void-input');
var q = root.querySelector('.mde-search-void-q');
var count = root.querySelector('.mde-search-void-count');
var clear = root.querySelector('.mde-search-void-clear');
var hits = ['quantum ledger', 'quarterly ledger', 'ledger exports'];

function sync() {
  var v = (input.value || '').trim();
  q.textContent = v || 'an empty query';
  var found = hits.indexOf(v.toLowerCase()) > -1;
  root.setAttribute('data-state', found ? 'found' : 'empty');
  if (found) count.textContent = '3 documents for ' + v;
}

input.addEventListener('input', sync);
clear.addEventListener('click', function () {
  input.value = '';
  sync();
  input.focus();
});
Array.prototype.forEach.call(root.querySelectorAll('.mde-search-void-chip'), function (b) {
  b.addEventListener('click', function () {
    input.value = b.getAttribute('data-q');
    sync();
  });
});
sync();

