js:
var btn = root.querySelector('.mde-retry-fault-retry');
var toggle = root.querySelector('.mde-retry-fault-toggle');
var title = root.querySelector('.mde-retry-fault-title');
var sub = root.querySelector('.mde-retry-fault-sub');
var status = root.querySelector('.mde-retry-fault-status');
var log = root.querySelector('.mde-retry-fault-log');
var attempt = 1;
var timer = 0;

toggle.addEventListener('click', function () {
  var open = root.classList.toggle('is-open');
  toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
});

btn.addEventListener('click', function () {
  if (root.getAttribute('data-state') === 'ok') {
    attempt = 1;
    root.setAttribute('data-state', 'error');
    title.textContent = 'Could not load transactions';
    sub.textContent = 'The ledger service stopped responding. Nothing was lost — your data is intact.';
    btn.textContent = 'Try again';
    status.textContent = 'Attempt 1 of 3 failed after 30s';
    return;
  }
  root.setAttribute('data-state', 'busy');
  btn.disabled = true;
  btn.textContent = 'Retrying…';
  status.textContent = 'Reconnecting to ledger-eu-west-1…';
  clearTimeout(timer);
  timer = setTimeout(function () {
    if (!root.isConnected) return;
    btn.disabled = false;
    attempt += 1;
    if (attempt >= 3) {
      root.setAttribute('data-state', 'ok');
      title.textContent = 'Connection restored';
      sub.textContent = '1,284 transactions loaded from the ledger service.';
      btn.textContent = 'Refresh again';
      status.textContent = 'Recovered on attempt 3 · latency 240ms';
      log.textContent = 'GET /v2/ledger/transactions\n200 OK · req_c40de911\nupstream: ledger-eu-west-1';
    } else {
      root.setAttribute('data-state', 'error');
      btn.textContent = 'Try again';
      status.textContent = 'Attempt ' + attempt + ' of 3 failed after 30s';
    }
  }, 1500);
});

