js:
var btn = root.querySelector('.mde-offline-signal-btn');
var title = root.querySelector('.mde-offline-signal-title');
var sub = root.querySelector('.mde-offline-signal-sub');
var status = root.querySelector('.mde-offline-signal-status');
var tries = 0;
var timer = 0;

btn.addEventListener('click', function () {
  if (root.getAttribute('data-state') === 'online') return;
  tries += 1;
  root.setAttribute('data-state', 'checking');
  btn.disabled = true;
  btn.textContent = 'Checking…';
  status.textContent = 'Probing network';
  clearTimeout(timer);
  timer = setTimeout(function () {
    if (!root.isConnected) return;
    if (tries >= 2) {
      root.setAttribute('data-state', 'online');
      title.textContent = 'Back online';
      sub.textContent = 'All three pending changes were pushed to the server.';
      btn.textContent = 'Synced';
      status.textContent = 'Queue empty';
      Array.prototype.forEach.call(root.querySelectorAll('.mde-offline-signal-row em'), function (e) {
        e.textContent = 'synced';
      });
    } else {
      root.setAttribute('data-state', 'offline');
      btn.disabled = false;
      btn.textContent = 'Retry connection';
      status.textContent = 'Still offline · attempt ' + tries;
    }
  }, 1300);
});

