var sub = root.querySelector('.mde-locked-vault-sub');
var note = root.querySelector('.mde-locked-vault-note');
var timer = 0;

req.addEventListener('click', function () {
  if (root.getAttribute('data-state') === 'sent') return;
  root.classList.add('is-shake');
