var steps = Array.prototype.slice.call(root.querySelectorAll('.mde-first-run-step'));
var fill = root.querySelector('.mde-first-run-fill');
var count = root.querySelector('.mde-first-run-count');
var sub = root.querySelector('.mde-first-run-sub');
var C = 113.1;

function sync() {
  var done = steps.filter(function (s) { return s.getAttribute('aria-pressed') === 'true'; }).length;
  fill.style.strokeDashoffset = String(C - C * (done / steps.length));
  count.textContent = done + '/' + steps.length;
  root.setAttribute('data-state', done === steps.length ? 'done' : 'start');
  sub.textContent = done === steps.length
    ? 'Every step is complete. Nice work.'
    : 'Nothing here yet. ' + (steps.length - done) + ' short steps and your workspace goes live.';
}

steps.forEach(function (s) {
  s.addEventListener('click', function () {
    s.setAttribute('aria-pressed', s.getAttribute('aria-pressed') === 'true' ? 'false' : 'true');
    sync();
  });
});
sync();

