var scene = root.querySelector('.mde-lost-404-scene');
var stars = root.querySelector('.mde-lost-404-stars');
var orbit = root.querySelector('.mde-lost-404-orbit');
var num = root.querySelector('.mde-lost-404-num');
var calm = false;
try { calm = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { calm = false; }

function shift(x, y) {
  stars.style.transform = 'translate(' + (x * 5) + 'px,' + (y * 4) + 'px)';
  orbit.style.transform = 'translate(' + (x * 10) + 'px,' + (y * 7) + 'px)';
  num.style.transform = 'translate(calc(-50% + ' + (x * -6) + 'px),calc(-50% + ' + (y * -4) + 'px))';
}

if (!calm) {
  scene.addEventListener('pointermove', function (e) {
    var r = scene.getBoundingClientRect();
    if (!r.width || !r.height) return;
    shift((e.clientX - r.left) / r.width * 2 - 1, (e.clientY - r.top) / r.height * 2 - 1);
  });
  scene.addEventListener('pointerleave', function () { shift(0, 0); });
}
